import threading

def reproduce(connect, service) -> str | None:
    ACCT = 1
    NTHREADS = 16
    PER_THREAD = 5
    AMOUNT = 100

    try:
        with connect() as conn:
            row = conn.execute("SELECT balance FROM accounts WHERE id = %s", (ACCT,)).fetchone()
            if row is None:
                return None
            initial = row[0]
    except Exception:
        return None

    barrier = threading.Barrier(NTHREADS)
    state_lock = threading.Lock()
    ok_count = [0]
    err_count = [0]

    def worker():
        try:
            barrier.wait()
        except Exception:
            pass
        for _ in range(PER_THREAD):
            conn = None
            try:
                with connect() as c:
                    service.deposit(c, ACCT, AMOUNT)
                    with state_lock:
                        ok_count[0] += 1
            except Exception:
                with state_lock:
                    err_count[0] += 1

    threads = [threading.Thread(target=worker) for _ in range(NTHREADS)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    # If anything errored, treat as inconclusive to avoid false alarms.
    if err_count[0] > 0:
        return None
    total = NTHREADS * PER_THREAD
    if ok_count[0] != total:
        return None

    try:
        with connect() as conn:
            row = conn.execute("SELECT balance FROM accounts WHERE id = %s", (ACCT,)).fetchone()
            final = row[0]
    except Exception:
        return None

    expected = initial + total * AMOUNT
    if final != expected:
        return f"lost update: account {ACCT} balance is {final} but {total} successful deposits of {AMOUNT} from {initial} should give {expected}"
    return None

